    def menu(self):
        self.clear()
        nameList = ['stats', 'past games', 'opponent info', 'comment', 'game info', 'all infomation', 'save game', 'end game']   #YUHTYGHBJFGYKFutuerhnrurjkrfhrirnrirbnrurjnrirnrorjroj
        xcord = 20
        ycord = 90
        self.window = finn.Tk()
        self.window.geometry("3000x3000")
        BimmageHolder = []
        NameHolder = []
        Bimmages = []
        BimmageName = ttk.Label(self.window, text="What would you like to do?", font=("Lexend", 40))
        BimmageName.place(x=400, y=30)
        for nam in nameList:
            if nam in self.pics:
                name = nam
            else:
                name = str(random.randint(1, 25))
            pill = Image.open(io.BytesIO(base64.b64decode(self.pics[name])))
            pill = pill.resize((200, 200))

            Bimmage = ImageTk.PhotoImage(pill)

            Bimmages.append(Bimmage)
            DoneBimmage = ttk.Button(self.window, image=Bimmage, command=lambda x=nam: self.printMenu(x))
            BimmageName = ttk.Label(self.window, text=nam, font=("Lexend", 15))
            BimmageHolder.append(DoneBimmage)
            NameHolder.append(BimmageName)
        for i in range(len(BimmageHolder)):
            if xcord >= 1400:
                xcord = 0
                ycord += 230
            BimmageHolder[i].place(x=xcord + 30, y=ycord)
            NameHolder[i].place(x=xcord + 35, y=ycord + 5) 
            xcord += 270
        self.window.mainloop()


