    def modePicked(self, name):
        self.clear()
        self.MODENAME = name 
    
    def getTheMode(self):
        return self.MODENAME
    def add(self):
        self.points += 5
        self.counter.config(text=self.points)

    def subtract(self):
        self.points -= 5
        self.counter.config(text=self.points)

    def doPoints(self, currentPoints = 0):
        self.points = currentPoints
        xcord = 0
        ycord = 270
        self.window = finn.Tk()
        self.window.geometry("830x830")
        BimmageHolder = []
        NameHolder = []
