        Bimmages.append(Bimmage)
        DoneBimmage = ttk.Button(self.window, image=Bimmage, command=lambda :self.subtract())
        BimmageName = ttk.Label(self.window, text="-5", font=("Lexend", 24))
        BimmageHolder.append(DoneBimmage)
        NameHolder.append(BimmageName)
        pill = Image.open(io.BytesIO(base64.b64decode(self.pics["end"])))
