class Player():
   def __init__(self, name, Quacks, goalQuacks):
      self.name = name
      self.Quacks = Quacks
      self.goalQuacks = goalQuacks
      self.betHistory = []
      self.choiceHistory = []
   def __str__(self):
      return  f"Name: {self.name}\nQuacks: {self.Quacks}\nGoal Quacks: {self.goalQuacks}\nBetting History: {self.betHistory}\nChoices: {self.choiceHistory}"
   def update(self, Quacks, bet, choice):
      self.Quacks = Quacks
      self.betHistory.append(bet)
      self.choiceHistory.append(choice)
   def getQuacks(self):
      return self.Quacks
   def getGoalQuacks(self):
       return self.goalQuacks
   def getName(self):
       return self.name
   def setName(self, name, goal, bets, choices):
       self.name = name
       self.goalQuacks = goal
       self.betHistory = ast.literal_eval(bets)
       self.choiceHistory = ast.literal_eval(choices)


